/* ---------------- viewport sizing ----------------
   The stage is fluid now, so the drawing buffer, the projection and the sky
   aspect all follow the CSS box instead of a baked 960x540.                */
let VIEW_W = 960, VIEW_H = 540, ASPECT = 960 / 540;
const MAX_BUFFER_W = 2560; // keep the fill rate sane on 4K / hidpi screens

function resizeGL() {
  const c = $('gl');
  const cw = c.clientWidth || 960, ch = c.clientHeight || 540;
  const dpr = Math.min(window.devicePixelRatio || 1, 2);
  let bw = Math.max(1, Math.round(cw * dpr));
  let bh = Math.max(1, Math.round(ch * dpr));
  if (bw > MAX_BUFFER_W) { bh = Math.max(1, Math.round(bh * MAX_BUFFER_W / bw)); bw = MAX_BUFFER_W; }
  if (c.width !== bw || c.height !== bh) { c.width = bw; c.height = bh; }
  VIEW_W = bw; VIEW_H = bh; ASPECT = bw / bh;
  proj = persp(1.15, ASPECT, 0.08, 300);
  if (gl) gl.viewport(0, 0, bw, bh);
  document.documentElement.style.setProperty('--ui', (clamp(cw / 960, 1, 1.75)).toFixed(3));
  const badge = $('bRes');
  if (badge) badge.textContent = bw + ' x ' + bh;
}

function drawParts(parts) {
  for (const e of parts) {
    gl.bindBuffer(gl.ARRAY_BUFFER, e.vbo);
    gl.vertexAttribPointer(0, 3, gl.FLOAT, false, 24, 0);
    gl.vertexAttribPointer(1, 2, gl.FLOAT, false, 24, 12);
    gl.vertexAttribPointer(2, 1, gl.FLOAT, false, 24, 16);
