/* ---------------- player / physics ---------------- */
const HW = 0.3, PH = 1.8, EYE = 1.62;
const player = {
  pos: [31.5, 20, 31.5], vel: [0, 0, 0],
  yaw: -0.37, pitch: -0.05,
  onGround: false, fly: false, slot: 0,
