function solidAt(x, y, z) {
  if (y < 0) return true;
  if (x < 0 || x >= W || z < 0 || z >= D) return true;
  if (y >= H) return false;
  return SOLID_SET.has(B[idx(x, y, z)]);
}
function boxHits(px, py, pz) {
  const x0 = Math.floor(px - HW), x1 = Math.floor(px + HW);
  const y0 = Math.floor(py), y1 = Math.floor(py + PH);
  const z0 = Math.floor(pz - HW), z1 = Math.floor(pz + HW);
  for (let y = y0; y <= y1; y++)
    for (let x = x0; x <= x1; x++)
      for (let z = z0; z <= z1; z++)
        if (solidAt(x, y, z)) return true;
