}
function moveAxis(axis, amt) {
  player.pos[axis] += amt;
  if (!boxHits(player.pos[0], player.pos[1], player.pos[2])) return false;
  const p = player.pos;
  if (axis === 0) p[0] = amt > 0 ? Math.floor(p[0] + HW) - HW - 1e-4 : Math.floor(p[0] - HW) + 1 + HW + 1e-4;
  if (axis === 2) p[2] = amt > 0 ? Math.floor(p[2] + HW) - HW - 1e-4 : Math.floor(p[2] - HW) + 1 + HW + 1e-4;
  if (axis === 1) {
    if (amt > 0) p[1] = Math.floor(p[1] + PH) - PH - 1e-4;
    else { p[1] = Math.floor(p[1]) + 1 + 1e-4; player.onGround = true; }
  }
