}
const keys = new Set();
function currentWish() {
  let f = 0, s = 0;
  if (keys.has('KeyW') || keys.has('ArrowUp')) f++;
  if (keys.has('KeyS') || keys.has('ArrowDown')) f--;
  if (keys.has('KeyA') || keys.has('ArrowLeft')) s--;
  if (keys.has('KeyD') || keys.has('ArrowRight')) s++;
