}
function step1(h) {
  const p = player, v = p.vel;
  const [wx, wz] = currentWish();
  const eye = [p.pos[0], p.pos[1] + EYE, p.pos[2]];
  const inWater = bAt(eye[0], eye[1], eye[2]) === WATER ||
                  bAt(p.pos[0], p.pos[1] + 0.4, p.pos[2]) === WATER;
  const wasGround = p.onGround;
  p.onGround = false;
  const sprint = keys.has('ShiftLeft') || keys.has('ShiftRight');
  const speed = p.fly ? 9 : (sprint ? 6.2 : 4.4);

  if (p.fly) {
    v[0] = wx * speed; v[2] = wz * speed;
    let vy = 0;
    if (keys.has('Space')) vy += speed;
    if (sprint) vy -= speed;
    v[1] = vy;
  } else {
    const k = Math.min(1, h * 14);
    v[0] += (wx * speed - v[0]) * k;
    v[2] += (wz * speed - v[2]) * k;
    v[1] -= (inWater ? 9 : 26) * h;
    if (inWater) {
      v[1] *= Math.max(0, 1 - h * 2.2);
      if (keys.has('Space')) v[1] += 26 * h;
      v[1] = clamp(v[1], -4.5, 5.5);
    }
    if (keys.has('Space') && wasGround) v[1] = 8.6;
  }

  moveAxis(0, v[0] * h);
  moveAxis(2, v[2] * h);
  const hitY = moveAxis(1, v[1] * h);
