/* ---------------- raycast ---------------- */
function raycast(ox, oy, oz, dx, dy, dz, maxD) {
  let x = Math.floor(ox), y = Math.floor(oy), z = Math.floor(oz);
  let px = x, py = y, pz = z;
  const sx = dx > 0 ? 1 : -1, sy = dy > 0 ? 1 : -1, sz = dz > 0 ? 1 : -1;
  const tdx = dx !== 0 ? Math.abs(1 / dx) : Infinity;
  const tdy = dy !== 0 ? Math.abs(1 / dy) : Infinity;
  const tdz = dz !== 0 ? Math.abs(1 / dz) : Infinity;
  let tmx = dx !== 0 ? (dx > 0 ? (x + 1 - ox) : (ox - x)) * tdx : Infinity;
  let tmy = dy !== 0 ? (dy > 0 ? (y + 1 - oy) : (oy - y)) * tdy : Infinity;
  let tmz = dz !== 0 ? (dz > 0 ? (z + 1 - oz) : (oz - z)) * tdz : Infinity;
  for (let i = 0; i < 300; i++) {
    px = x; py = y; pz = z;
    if (tmx < tmy && tmx < tmz) { if (tmx > maxD) return null; x += sx; tmx += tdx; }
    else if (tmy < tmz)        { if (tmy > maxD) return null; y += sy; tmy += tdy; }
    else                       { if (tmz > maxD) return null; z += sz; tmz += tdz; }
    const b = blk(x, y, z);
    if (b !== AIR) return { x, y, z, px, py, pz, b };
    if (y < -8) break;
  }
  return null;
}
function eyePos() { return [player.pos[0], player.pos[1] + EYE, player.pos[2]]; }
function fwdVec() {
  const cp = Math.cos(player.pitch);
  return [
    cp * Math.sin(player.yaw),
    -Math.sin(player.pitch),
    -cp * Math.cos(player.yaw),
  ];
}
function doRay() { const e = eyePos(), f = fwdVec(); return raycast(e[0], e[1], e[2], f[0], f[1], f[2], 6); }

let lastEdit = 0;
function setBlock(x, y, z, v) {
  B[idx(x, y, z)] = v;
  lastEdit = performance.now();
  buildMesh();
}
function mine() {
  const r = doRay();
  if (!r) return;
  if (r.b === WATER) { say("CAN'T MINE WATER. TRY THE LANDS."); return; }
  if (r.b === BEDROCK) { say('BEDROCK IS PERMANENT, LIKE THIS SITE\'S LAYOUT.'); return; }
  setBlock(r.x, r.y, r.z, AIR);
  blip(180, 0.12, 0.30);
  say('MINED: ' + BLOCK_NAME[r.b]);
}
function place() {
  const r = doRay();
  if (!r) return;
  const { px, py, pz } = r;
  if (px < 0 || px >= W || py <= 0 || py >= H || pz < 0 || pz >= D) return;
  const cur = blk(px, py, pz);
  if (cur !== AIR && cur !== WATER) return;
  const p = player.pos;
  const overlap =
    px + 1 > p[0] - HW && px < p[0] + HW &&
    py + 1 > p[1] && py < p[1] + PH &&
    pz + 1 > p[2] - HW && pz < p[2] + HW;
  if (overlap) { say('THAT CELL IS OCCUPIED (BY YOU).'); return; }
  setBlock(px, py, pz, HOTBAR[player.slot].id);
  blip(430, 0.09, 0.24);
  say('PLACED: ' + HOTBAR[player.slot].name);
}

/* ---------------- render ---------------- */
let target = null;
function render(t) {
  const e = eyePos();
  const view = makeView(e, player.yaw, player.pitch);
  gl.viewport(0, 0, VIEW_W, VIEW_H);
  gl.enable(gl.DEPTH_TEST);
  gl.clear(gl.COLOR_BUFFER_BIT | gl.DEPTH_BUFFER_BIT);

  // sky
  gl.disable(gl.DEPTH_TEST);
  gl.useProgram(S.p);
  const cp = Math.cos(player.pitch);
  const fy = Math.sin(player.yaw), cy = Math.cos(player.yaw);
  const sp = Math.sin(player.pitch);
  gl.uniform3f(S.u.fwd, cp * fy, -sp, -cp * cy);
  gl.uniform3f(S.u.right, cy, 0, fy);
  gl.uniform3f(S.u.up, cp * fy * sp, cp * cp, -cp * cy * sp);
  gl.uniform1f(S.u.tan, Math.tan(1.15 / 2));
  gl.uniform1f(S.u.aspect, ASPECT);
  gl.uniform1f(S.u.time, t * 0.001);
  gl.bindBuffer(gl.ARRAY_BUFFER, triVbo);
  gl.vertexAttribPointer(0, 2, gl.FLOAT, false, 8, 0);
  gl.drawArrays(gl.TRIANGLES, 0, 3);
  gl.enable(gl.DEPTH_TEST);

  // terrain
  target = doRay();
  gl.useProgram(T.p);
  gl.uniformMatrix4fv(T.u.proj, false, proj);
  gl.uniformMatrix4fv(T.u.view, false, view);
  gl.uniform3fv(T.u.fog, FOG);
  gl.activeTexture(gl.TEXTURE0);
  gl.bindTexture(gl.TEXTURE_2D, tex);
  gl.uniform1i(T.u.tex, 0);
  gl.enable(gl.CULL_FACE);
  drawParts(OP);
  gl.enable(gl.BLEND);
  gl.blendFunc(gl.SRC_ALPHA, gl.ONE_MINUS_SRC_ALPHA);
  gl.depthMask(false);
  gl.disable(gl.CULL_FACE);
  drawParts(WP);
  gl.depthMask(true);
  gl.disable(gl.BLEND);

  // highlight
  if (target) {
    gl.useProgram(L.p);
    gl.uniformMatrix4fv(L.u.mvp, false, mat4Mul(proj, view));
    gl.uniform3f(L.u.off, target.x, target.y, target.z);
    gl.uniform4f(L.u.color, 1, 1, 1, 0.5 + 0.35 * Math.sin(t * 0.008));
    gl.bindBuffer(gl.ARRAY_BUFFER, lineVbo);
    gl.vertexAttribPointer(0, 3, gl.FLOAT, false, 12, 0);
    gl.enable(gl.BLEND);
    gl.blendFunc(gl.SRC_ALPHA, gl.ONE_MINUS_SRC_ALPHA);
    gl.lineWidth(2);
    gl.drawArrays(gl.LINES, 0, 24);
    gl.disable(gl.BLEND);
  }

  $('waterTint').style.display =
    (bAt(e[0], e[1], e[2]) === WATER) ? 'block' : 'none';
}

