/* ---------------- audio (laser-wave chiptune) ---------------- */
let AC = null, master = null, noiseBuf = null, audioOn = true;
const LEAD = [220, 0, 261.63, 0, 329.63, 0, 0, 659.26,
              220, 0, 261.63, 0, 329.63, 392, 440, 523.25];
const BASSROOT = [110, 110, 82.41, 98];
let nextT = 0, stepN = 0;

function initAudio() {
  if (AC) return;
  try {
    AC = new (window.AudioContext || window.webkitAudioContext)();
  } catch (e) { return; }
  master = AC.createGain();
  master.gain.value = 0.38;
  master.connect(AC.destination);
  noiseBuf = AC.createBuffer(1, AC.sampleRate * 0.05, AC.sampleRate);
  const d = noiseBuf.getChannelData(0);
  for (let i = 0; i < d.length; i++) d[i] = Math.random() * 2 - 1;
  nextT = AC.currentTime + 0.1; stepN = 0;
  setInterval(sched, 40);
}
function sched() {
  if (!AC || AC.state !== 'running') return;
  const spb = 60 / 150 / 4;
  while (nextT < AC.currentTime + 0.15) {
    if (audioOn) playStep(stepN, nextT);
    stepN = (stepN + 1) % 16;
    nextT += spb;
  }
}
function tone(freq, dur, vol, t, type) {
  const o = AC.createOscillator(), g = AC.createGain();
  o.type = type || 'square';
  o.frequency.value = freq;
  g.gain.setValueAtTime(vol, t);
  g.gain.exponentialRampToValueAtTime(0.0008, t + dur);
  o.connect(g); g.connect(master);
  o.start(t); o.stop(t + dur + 0.03);
}
function playStep(s, t) {
  const f = LEAD[s];
  if (f) tone(f, 0.10, 0.11, t);
  if (s % 4 === 0) tone(BASSROOT[s / 4], 0.17, 0.17, t);
  const hs = AC.createBufferSource(); hs.buffer = noiseBuf;
  const hg = AC.createGain();
  hg.gain.setValueAtTime(s % 2 ? 0.045 : 0.022, t);
  hg.gain.exponentialRampToValueAtTime(0.001, t + 0.04);
  const hf = AC.createBiquadFilter(); hf.type = 'highpass'; hf.frequency.value = 6500;
  hs.connect(hf); hf.connect(hg); hg.connect(master);
  hs.start(t); hs.stop(t + 0.05);
}
