  try { visits = +(localStorage.getItem('rc_visits') || 0) + 1; localStorage.setItem('rc_visits', visits); } catch (e) { visits = 1; }
  const n = (42137 + days * 7 + visits).toString().padStart(6, '0');
  $('vcounter').textContent = n;
  $('ovCounter').textContent = 'VISITOR № ' + n + ' SINCE 1.1.1996';
})();

/* hotbar */
function buildHotbar() {
  const hb = $('hotbar');
  HOTBAR.forEach((b, i) => {
    const d = document.createElement('div');
    d.className = 'slot' + (i === 0 ? ' sel' : '');
    const c = document.createElement('canvas');
    c.width = 16; c.height = 16;
    c.getContext('2d').drawImage(atlasCanvas, b.icon * 16, 0, 16, 16, 0, 0, 16, 16);
    d.appendChild(c);
    const k = document.createElement('span');
    k.className = 'key'; k.textContent = String(i + 1);
    d.appendChild(k);
    d.title = b.name;
    d.addEventListener('mousedown', e => e.stopPropagation());
    d.addEventListener('click', () => { selectSlot(i); say(b.name + ' SELECTED'); });
    hb.appendChild(d);
  });
}

/* ---------------- main loop ---------------- */
let last = performance.now();
function frame(t) {
  requestAnimationFrame(frame);
  let dt = (t - last) / 1000;
  last = t;
  dt = Math.min(dt, 0.1);
  if (playing) physics(dt);
  try {
    render(t);
    updateHUD(t);
  } catch (err) {
    if (performance.now() - (frame.errAt || 0) > 2000) {
      frame.errAt = performance.now();
      console.error(err);
      say('GPU DROVE ITSELF OFF A CLIFF: ' + err.message);
    }
  }
}

